C = dict(id='GL-18', title='Online Currency Exchange Concepts', group='Digital and Technology', level=3,
 summary='Understand how currency exchange works online, compare rates and fees honestly, and design a safe, transparent exchange-service concept without handling real funds.',
 outcomes=['Explain exchange rates, spread, fees and why they differ between providers.', 'Calculate the true cost of a transfer from rate, fee and spread.', 'Analyse providers on cost, speed, safety and rules.', 'Create a customer guide and a transparent price display concept.', 'Evaluate the risks of fraud, rate change and legal duties.'],
 task='Compare five public exchange routes for one real need, calculate the true cost, and design a transparent price display and risk plan (no real money handled).',
 cond='A computer, public rate data, a spreadsheet, practice transactions only, a mentor with finance experience and a peer circle. About 8 weeks part-time.',
 std='Every cost shown in both currencies; true cost % calculated for five routes; fees and spread separated; scam checklist completed; concept reviewed by a mentor as honest and clear.',
 who='Small traders, travellers, finance learners, support staff, students.', req='Basic arithmetic.',
 safety='Concepts and practice only. Offering exchange services needs a licence in most places. Never take or hold real customer money in this course. Not financial or legal advice.',
 mods=[
 ('How exchange works', 'A rate says how much of one currency you get for another.', ['Quote like EUR 1 = INR 90 means 1 euro buys 90 rupees.', 'Mid-market rate is the middle of buy and sell prices.', 'Providers add a spread and fees.', 'Rates move every second.'], 'Mid-market 1 EUR = 90.00 INR. Provider offers 88.20: spread = (90 - 88.2) / 90 = 2%.', 'Convert five amounts in both directions.', 'All conversions correct with currency shown.'),
 ('True cost', 'The advertised rate is not the whole price.', ['True cost = (mid-market value - what receiver gets) / mid-market value.', 'Add fixed fees, card fees and receiver bank fees.', 'Compare same amount, same day.', 'Watch for "zero fee" offers with poor rates.'], 'Send EUR 500: mid value INR 45,000. Receiver gets INR 43,900 after a 3 EUR fee and 1.8% spread. True cost = 1,100 / 45,000 = 2.4%.', 'Calculate true cost for three real quotes.', 'Percentages correct.'),
 ('Comparing routes', 'Bank, card, cash, online provider, wallet: each has trade-offs.', ['Cost, speed, limits, safety, convenience.', 'Public comparison tools and their limits.', 'Time of day and weekends.', 'Who regulates each route.'], 'Bank wire: 3 days, 3.5%. Online provider: 1 day, 1.4%. Cash agent: instant, 4%.', 'Build a five-route comparison table.', 'Table has all five measures.'),
 ('Safety and scams', 'Exchange attracts fraud.', ['Fake rates too good to be true; pressure to act now.', 'Unlicensed providers; checks on the regulator\'s public list.', 'Never send money to personal accounts for a "business".', 'Keep records of every transfer.'], 'An offer promises a rate 8% above market: reject it; check the public register; report if fake.', 'Complete a scam checklist on three adverts.', 'Red flags named for each.'),
 ('Rules and duties', 'Providers must follow identity and anti-crime rules.', ['Licence, identity checks, limits and reports.', 'Record-keeping periods.', 'Taxes and declared limits at borders.', 'Consumer protection and complaints routes.'], 'A provider asks for ID above a set amount: that is a legal duty, not an insult.', 'Summarise the rules for your place in one page.', 'Page names the regulator and key limits.'),
 ('Design a transparent display', 'Show the total before the customer commits.', ['Show mid-market rate, our rate, fee and total received.', 'Show the time to arrive.', 'Lock the rate for a short time and say how long.', 'Show how to complain.'], 'Screen: "You send EUR 500. Mid-market 90.00. Our rate 89.10. Fee EUR 3. You get INR 44,247. Rate held 5 minutes."', 'Sketch the price screen.', 'Every number labelled with currency.'),
 ('Risk plan', 'Rates move and systems fail.', ['Rate risk: hold time and limits.', 'Operational risk: down time and wrong entries.', 'Fraud risk: checks and limits.', 'Liquidity: having enough of each currency.'], 'A rate falls 1.5% during a 10-minute delay: the price lock protects the customer and a limit protects the business.', 'Write a risk table with six rows.', 'Each row has a control and an owner.'),
 ('Present and plan', 'Explain the concept clearly and honestly.', ['One page: need, routes compared, display, risks, rules.', 'State what is concept only.', 'Gather feedback from a trader or traveller.', 'Plan 90 days: licence path, advisers.'], 'Feedback: "Show total in rupees first." Change made and retested.', 'Present to peers and mentor.', 'Feedback recorded and applied.')],
 quiz=[('What is a spread?', 'The gap between mid-market and the rate you are offered.'), ('Calculate true cost.', '(Mid-market value minus received) divided by mid-market value.'), ('Why compare the same day?', 'Rates change constantly.'), ('Red flag in an offer?', 'A rate far better than the market or pressure to hurry.'), ('Why are ID checks needed?', 'Legal duties to prevent crime.'), ('What should a display show?', 'Rate, fee, total received, time and complaint route.'), ('What is rate risk?', 'The rate moves before the deal completes.'), ('What does "zero fee" hide?', 'Possibly a poor rate.'), ('May this course hold real money?', 'No, concepts only.'), ('Where to check licences?', 'The regulator\'s public register.')],
 rubric=[('Calculations', 'True cost correct for five routes', 'Sensitivity to rate change shown'), ('Comparison', 'Five measures per route', 'Recommendation matched to user need'), ('Safety', 'Scam checklist used', 'Reports on suspicious ads'), ('Design', 'Transparent display drafted', 'Users understand it in 10 seconds'), ('Rules awareness', 'Regulator and limits named', 'Licence path outlined')],
 jobs=[('Currency desk assistant', 'Supports quotes and records'), ('Payments support agent', 'Explains fees and rates'), ('Travel finance assistant', 'Helps customers compare options'), ('Compliance support assistant', 'Runs checklists')],
 next='Wallet Payment Solutions; P2P Lending Platform Concepts; Blockchain Health-Record Concepts.',
 local='Exchange licences, limits and tax declarations differ by country: always check the local regulator before any service idea.',
 evidence='Your evidence: conversions, true-cost table, five-route comparison, scam checklist, rules page, price-screen sketch and risk table.',
 ladder=[('Basics of money abroad', 'Convert amounts. Notes: use a calculator.'), ('Awareness', 'Know rates and fees. Notes: read a real rate card.'), ('Foundation', 'This course. Notes: true cost and design.'), ('Practitioner', 'Support a desk with supervision. Notes: practice only.'), ('Specialist', 'Treasury and risk. Notes: hedging concepts.'), ('Advanced', 'Lead compliance and operations. Notes: audits.'), ('Super expert', 'Set the quote-comparison and fee-disclosure method for currency exchange and teach the advisers who use it. Notes: re-read the exchange rules for each place yearly and refresh the sample rate cards.')])

C['deep'] = dict(mods=[
 ('Confusing buy and sell rates.', 'Bank buys at 88 and sells at 92 against mid 90; know which side you are on.', 'Which rate applies to you?'),
 ('Forgetting fixed fees on small amounts.', 'A 3.00 fee on 50.00 is 6% before spread.', 'What is the fee as a percent?'),
 ('Comparing different days.', 'Rates moved 0.8% in an hour; compare within ten minutes.', 'When did you take each quote?'),
 ('Trusting a too-good rate.', 'An offer 8% above market is a scam sign.', 'Which red flag did you find?'),
 ('Ignoring identity rules.', 'A provider\'s ID request is a legal duty.', 'What limit applies where you live?'),
 ('Showing the rate but not the total.', 'The screen shows total received first in large type.', 'What is the first number your user sees?'),
 ('No rate-lock time.', 'The rate holds for 5 minutes, then refreshes.', 'How long is your hold?'),
 ('Presenting concept as ready.', 'Summary says "concept only, no real money".', 'What did you state as limits?')],
 gloss=[('Mid-market rate', 'Middle of buy and sell prices.'), ('Spread', 'Gap between mid and offered rate.'), ('True cost', 'All costs as a percent of the amount.'), ('Rate lock', 'A fixed rate for a short time.'), ('Regulator', 'The authority that licenses providers.'), ('Remittance', 'Money sent abroad.')],
 cases=[('The cheap-looking transfer', 'A provider shows "0 fee".', 'How check?', 'Compare received amount with mid-market and compute true cost.'),
        ('The pressure call', 'A caller says the rate expires in ten minutes and asks for a personal transfer.', 'What do you do?', 'Stop, verify the provider on the regulator\'s list, and report.')])
C['deep']['extra'] = [
 ['Note that rates are quoted both ways (EUR/INR or INR/EUR); always say which.', 'Use a calculator and write the currency next to every number.'],
 ['Compare cost on small and large amounts; fixed fees hit small ones hardest.', 'Include the receiving bank\'s charges.'],
 ['Take screenshots of quotes with the time.', 'Check how long money takes to arrive.'],
 ['Use only the regulator\'s register to check a provider.', 'Never share one-time codes.'],
 ['Learn thresholds for reporting large amounts in your place.', 'Keep records for the required period.'],
 ['Use the customer\'s currency for the headline number.', 'Add a short plain note on how to complain.'],
 ['Plan for system downtime and wrong rates.', 'Keep enough of each currency to meet daily demand.'],
 ['Describe the next step as getting a licence or partnering with one.', 'Keep the concept free of any promise of profit.']]

_ex = ['Mid-market 1 EUR = 90.00 INR. A provider offers 88.20: the spread is (90 - 88.2) / 90 = 2%.', 'Send EUR 500: mid-value INR 45,000. The receiver gets INR 43,900 after a 3 EUR fee and spread. True cost = 1,100 / 45,000 = 2.4%.', 'Bank wire: 3 days, 3.5%. Online provider: 1 day, 1.4%. Cash agent: instant, 4%. Table lets a traveller pick on cost or speed.', 'An offer promises a rate 8% above market. You check the public register, find no licence and report it.', 'A provider asks for ID above a set amount. That is a legal duty to prevent crime, not an insult.', "Screen: 'You send EUR 500. Mid-market 90.00. Our rate 89.10. Fee EUR 3. You get INR 44,247. Rate held 5 minutes.'", 'A rate falls 1.5% during a 10-minute delay. The price lock protects the customer and a limit protects the business.', "Feedback: 'Show total in rupees first.' The change is made and a second tester understands in 10 seconds."]
_extra = ['Convert five amounts both ways and check with a second calculator.', 'Write which currency is quoted and which is the base.', 'Record the date and time of every quote.', "Find the regulator's public list of licensed providers.", 'Never share one-time codes or passwords with anyone.', 'Compare the cost for a small and a large amount.', 'Look at how long each route takes on weekends.', 'Check whether the receiver pays a fee too.', 'Keep screenshots of every quote.', 'Learn which documents are needed to send money.', 'Write what happens if a transfer fails.', 'List how to complain, step by step.', 'Draw the money flow including fees.', 'Remember this course holds no real money.', 'Write a short customer guide in plain words.', 'Ask a finance adviser to review your concept.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Treat the mid-market rate as the halfway point between buy and sell prices; if it is 1.10 and a provider offers 1.07, the gap of 0.03 is a hidden cost of about 2.7 percent.', 'Write down the currency pair both ways, such as A per B and B per A, and check which direction you are quoted, since mixing them causes errors of several percent.'], ['Add up three costs for any transfer: the fixed fee, the percentage fee, and the rate margin; then divide the total by the amount sent to get one honest percentage.', 'Compare two offers on a 1,000 unit transfer: a low fee with a poor rate may cost more than a higher fee with a rate near the mid-market, so always compute both.'], ['Build a comparison grid with at least four routes, such as bank, card, specialist transfer service and cash exchange, and record fee, rate, speed and receiver amount for the same sum.', 'Check the offer at two different times on the same day and note the difference, since quotes move and ask whether the provider will lock a quoted rate for 30 minutes.'], ['Check any provider by searching its registration on an official register, confirming the website address letter by letter, and refusing anyone who asks for payment in gift cards.', "Treat urgency as a warning: if a message says 'send within one hour for a special rate', stop, wait a day, and call the provider on a number you found yourself."], ['Keep records of each exchange for at least the period your local rules require, noting date, amount, rate, fee and reason, since these may be needed for reporting or tax.', 'Learn the identity checks providers ask for and why they exist, and prepare documents in advance so a first transfer is not delayed by days.'], ['Display the final receiver amount in the largest text on the screen, and show the rate, the fee and the mid-market rate on the same line so nothing is hidden.', "Show a countdown for how long a quote stays valid, such as 'rate held for 10:00', and say what happens when it expires so users are not surprised."], ['List five risks with a rating: rate moves before sending, wrong recipient details, delayed delivery, fraud and provider failure; write one protective step for each.', 'Set a plan for rate moves, such as locking the rate for large amounts or splitting a transfer into two parts a week apart so a single bad day matters less.'], ['Prepare a five-minute presentation with the cost comparison, your display design, your top three risks and a clear next step, such as a pilot with invented figures.', 'End with a short action plan dated over four weeks, with one task per week, so your concept moves from idea to something that can be reviewed.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {1: '1 USD = 83.00 INR at mid-market. A provider offers 81.00, so the spread is (83 - 81) / 83 = 2.4%, which costs 2.40 rupees on every 100.', 2: 'Send GBP 300 when mid value is INR 31,200. The receiver gets INR 30,300 after a GBP 2 fee and a spread. The true cost is 900 / 31,200 = 2.9%.', 3: 'Sending money home: bank transfer 4 days at 3%; app 1 day at 1.2%; pickup counter, same hour, 4.5%. A migrant worker choosing for an urgent medical bill takes the counter and accepts the higher cost.', 4: "A message offers 'guaranteed profit, double your money in a week'. You search the public register, find no licence, check the website age, and report it instead of paying.", 5: 'A provider refuses a first transfer until a passport is shown, and keeps the copy for the legal period. The customer is told why, and the check takes 5 minutes.', 6: "Screen: 'You send USD 200. Mid-market 83.00. Our rate 81.90. Fee USD 2. You get INR 16,216. Delivered by tomorrow.' A tester can say the total cost without help.", 7: 'A business owner agrees a rate for a payment due in 30 days; the rate moves 2% against her. A forward contract with the provider fixes the rate and removes the surprise.', 8: 'A tester says the fee seems hidden. You move the total cost to the top of the screen, and the next three testers state the cost correctly in under 10 seconds.'}
C['deep']['mods'] = [(m[0], _dupfix.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]

_dupfix2 = {2: 'A student abroad sends GBP 300 home. The family receives INR 30,300 where mid value is INR 31,200, after one flat fee and a weak rate. Divide the 900 lost by 31,200 and the true cost is 2.9%.', 6: "A mock-up shows total cost in large type at the top: 'You pay USD 200. They receive INR 16,216. All fees included. Arrives tomorrow.' Details open below for anyone who wants them."}
C['deep']['mods'] = [(m[0], _dupfix2.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will read a quoted rate in both directions and spot the gap from the mid-market rate, which is where much of the real cost hides.', 'You will combine fixed fee, percentage fee and rate margin into one honest percentage, so two quotes can be compared fairly.', 'You will build a side-by-side grid of four routes for the same sum and see which one actually delivers the most to the receiver.', "You will check a provider's registration and recognise pressure tactics, protecting yourself and customers from the most common exchange frauds.", 'You will list the identity and record-keeping duties that apply to exchange services, so a concept is designed to meet them from day one.', 'You will design a screen that leads with the amount received and shows rate, fee and quote timer, so customers decide with full knowledge.', 'You will rate five exchange risks and attach a protective step to each, including a plan for when a rate moves against a transfer.', 'You will present a cost comparison, display design and risk list, then set a four-week plan for testing the concept with invented figures.']
